package com.clinic.controller; import org.springframework.web.bind.annotation.*; import com.clinic.model.Prescription; import com.clinic.repository.PrescriptionRepository; import java.util.*; @RestController @RequestMapping("/prescriptions") public class PrescriptionController{final PrescriptionRepository r;public PrescriptionController(PrescriptionRepository r){this.r=r;}@GetMapping public List<Prescription> all(){return r.findAll();}@GetMapping("/{id}") public Prescription one(@PathVariable Long id){return r.findById(id).orElseThrow(()->new RuntimeException("Prescription not found"));}@PostMapping public Prescription add(@RequestBody Prescription x){return r.save(x);}@PutMapping("/{id}") public Prescription put(@PathVariable Long id,@RequestBody Prescription x){x.id=id;return r.save(x);}@DeleteMapping("/{id}") public void del(@PathVariable Long id){r.deleteById(id);}}